module fixed_point_subtractor(
    parameter Q = 4,
    parameter N = 8,
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    assign c = res;
    always @* begin
        if (a[N-1] == b[N-1]) begin
            res = {a[N-1], a[N-2:0]} - {b[N-1], b[N-2:0]};
        end else begin
            // Different Sign Subtraction
            if ((a[N-1] > b[N-1]) || (a[N-1] == 0 && b[N-1] == 1)) begin
                res = a + (~b + 1);
                res[N-1] = 0;
            end else begin
                res = ~a + 1 + b;
                res[N-1] = 1;
            end
        end
    end

    // Handling zero
    always @* begin
        if (res == 0) begin
            res[N-1] = 0;
        end
    end
endmodule
